/// <summary>
/// The IR's published JSON Schema, one file per version in <c>schemas/ir</c>: the current one generated by <see cref="IrJsonSchema"/>, committed,
/// and held to the model, the writer and the reader. The committed file must be what the generator gives today; every IR
/// file haruspex writes must pass it, in the tests' own validator and in Ajv; and every property of every IR record must be in it, or be
/// named here as written another way. That the schema and the reader refuse the same files is <c>IrReaderSchemaAgreementTests</c>'.
/// </summary>
public class IrJsonSchemaTests
