    public static TheoryData<string> Snapshots { get; } =
        [.. Fixture.All.SelectMany(f => f.Snapshots).Select(s => Path.GetRelativePath(RepositoryPaths.Fixtures, s.Ir))];

    private static string SchemaPath => Path.Combine(RepositoryPaths.Root, SchemaFile);

    [Fact]
    public void The_committed_schema_is_what_the_model_generates()
    {
        var generated = IrJsonSchema.Write();
        var committed = File.Exists(SchemaPath) ? File.ReadAllText(SchemaPath).ReplaceLineEndings("\n") : null;
        if (committed == generated)
            return;

        // As SnapshotStore does: rewritten only when asked, and never in CI.
        if (Environment.GetEnvironmentVariable(SnapshotStore.AcceptVariable) == "1" && !SnapshotStore.IsCiEnvironment(Environment.GetEnvironmentVariable))
        {
            File.WriteAllText(SchemaPath, generated);
            return;
        }

        Assert.Fail(
            $"{SchemaFile} is not what IrJsonSchema generates from the model today. Regenerate it with " +
            $"{SnapshotStore.AcceptVariable}=1 dotnet test --filter {nameof(IrJsonSchemaTests)}, and read the diff. The difference:\n" +
            SnapshotStore.UnifiedDiff(committed ?? "", generated, SchemaFile, "what IrJsonSchema generates"));
    }

    [Fact]
    public void The_schema_is_a_2020_12_schema_with_its_id_and_the_versions_a_reader_reads()
    {
        using var schema = JsonDocument.Parse(IrJsonSchema.Write());

        Assert.Equal("https://json-schema.org/draft/2020-12/schema", schema.RootElement.GetProperty("$schema").GetString());
        Assert.Equal(IrJsonSchema.Id, schema.RootElement.GetProperty("$id").GetString());
        Assert.Equal(IrDocument.ReadableVersions, schema.RootElement.GetProperty("properties").GetProperty("irVersion").GetProperty("enum").EnumerateArray().Select(v => v.GetString()));
    }

    /// <summary>
    /// The schema is checked against the draft 2020-12 meta-schema and compiled in Ajv's strict mode, as a consumer who follows the
    /// guide would compile it: strict mode refuses a keyword it doesn't know, a <c>required</c> beside no <c>type</c> and a
    /// property required where none is defined, any of which a validator written for these tests alone could miss.
    /// </summary>
    [Fact]
    public void The_schema_is_a_valid_2020_12_schema_that_ajv_compiles_in_strict_mode()
    {
        EmitCheckPackage.RequireNode(RepositoryPaths.EmitCheck, "the IR schema was not compiled with Ajv");
        EmitCheckPackage.EnsureInstalled(RepositoryPaths.EmitCheck);

        Assert.True(
            EmitCheckPackage.TryRun("node", [Path.Combine("src", "meta-schema.mjs"), SchemaPath], RepositoryPaths.EmitCheck, out var output, out var why),
            $"{SchemaFile} doesn't compile in Ajv's strict mode ({why}):\n{output}");
        Assert.Contains("1 document(s), 0 failed", output, StringComparison.Ordinal);
    }

    /// <summary>The first version whose schema was published in <c>schemas/ir</c>; nothing was published for an earlier one.</summary>
    private const string FirstPublishedSchema = "0.29";

    /// <summary>
    /// Each file in <c>schemas/ir</c> is the schema of a version the format has had, named for it, at the address its <c>$id</c>
    /// names; every version from the first published, 0.29, to the current one has its file, as each has its file in
    /// <c>tests/ir-versions</c>; and each still validates that version's file there, in the tests' own validator and in Ajv. An older
    /// version's file is kept as it was when its version was current but for its <c>$id</c>, which moved to haruspex.tools with every
    /// other address (schemas/ir/README.md), since the generator writes only the current one.
    /// </summary>
    [Fact]
    public void Each_version_s_schema_is_named_for_it_and_still_validates_its_file()
    {
        var folder = Path.Combine(RepositoryPaths.Root, "schemas", "ir");
        var schemas = Directory.GetFiles(folder, "*.schema.json").Order(StringComparer.Ordinal).ToList();
        var versions = schemas.Select(f => Path.GetFileName(f)[..^".schema.json".Length]).ToList();

        var published = Directory.GetFiles(Path.Combine(RepositoryPaths.Root, "tests", "ir-versions"), "*.ir.json")
            .Select(f => Path.GetFileName(f)[..^".ir.json".Length])
            .Where(v => Version.Parse(v) >= Version.Parse(FirstPublishedSchema));
        Assert.Contains(IrDocument.CurrentVersion, versions);
        Assert.All(published, v => Assert.True(versions.Contains(v), $"Version {v} has a file in tests/ir-versions but no schema in schemas/ir: a version's schema stays when the version moves on."));
        foreach (var (schema, version) in schemas.Zip(versions))
        {
            var fixture = Path.Combine(RepositoryPaths.Root, "tests", "ir-versions", $"{version}.ir.json");
            Assert.True(File.Exists(fixture), $"schemas/ir/{Path.GetFileName(schema)} names no version the format has had: there is no {fixture}.");
            using var parsed = JsonDocument.Parse(File.ReadAllText(schema));
            Assert.Equal($"https://haruspex.tools/schemas/ir/{version}.schema.json", parsed.RootElement.GetProperty("$id").GetString());
            using var instance = JsonDocument.Parse(File.ReadAllText(fixture));
            Assert.Empty(new SchemaSubset(parsed.RootElement.Clone()).Validate(instance.RootElement));
            Assert.Empty(AjvVerdicts.Of(schema, new Dictionary<string, string> { [version] = File.ReadAllText(fixture) })[version]);
        }
    }

