    [Fact]
    public void The_samples_of_each_version_the_reader_reads_pass_the_schema() =>
        Assert.All([IrSamples.Everything, IrSamples.Combined, IrSamples.Derived, IrSamples.Whole, IrSamples.Binary, IrSamples.Declared, IrSamples.Stamped, IrSamples.Built, IrSamples.Folders, IrSamples.Described], d => AssertValid(IrJsonWriter.Write(d)));

    /// <summary>
    /// Every file haruspex writes passes the schema in Ajv too, a validator a consumer would use, compiled strictly: what the tests
    /// above check with <see cref="SchemaSubset"/>, written for the tests, which could read a keyword differently from a real one.
    /// <c>IrReaderSchemaAgreementTests</c> asks Ajv about every broken file.
    /// </summary>
    [Fact]
    public void Every_file_haruspex_writes_passes_the_schema_in_ajv_too()
    {
        var documents = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var snapshot in Snapshots)
            documents[snapshot.Data] = File.ReadAllText(Path.Combine(RepositoryPaths.Fixtures, snapshot.Data));
        foreach (var fixture in Fixture.All)
            documents[$"{fixture.Name}, inferred"] = IrJsonWriter.Write(fixture.Ir);
        foreach (var run in Corpus.Corpus.Runs)
            documents[$"{run.Corpus.Name}, inferred"] = IrJsonWriter.Write(run.Document);
        foreach (var (sample, i) in ((IrDocument[])[IrSamples.Everything, IrSamples.Combined, IrSamples.Derived, IrSamples.Whole, IrSamples.Binary, IrSamples.Declared, IrSamples.Stamped, IrSamples.Built, IrSamples.Folders, IrSamples.Described]).Select((d, i) => (d, i)))
            documents[$"sample {i}"] = IrJsonWriter.Write(sample);

        var verdicts = AjvVerdicts.Of(SchemaPath, documents);

        Assert.All(verdicts, v => Assert.True(v.Value.Count == 0, $"{v.Key}: Ajv refuses a file haruspex writes: {string.Join("; ", v.Value)}."));
    }

    [Fact]
    public void Every_property_of_every_ir_record_is_in_the_schema()
    {
        var records = typeof(IrDocument).Assembly.GetExportedTypes()
            .Where(t => t.GetMethod("<Clone>$") is not null && !t.IsAbstract && !t.IsSubclassOf(typeof(IrPathSegment)));
        var properties = records.SelectMany(t => t.GetProperties(BindingFlags.Public | BindingFlags.Instance).Select(p => $"{t.Name}.{p.Name}"));

        Assert.Equal(properties.Order(StringComparer.Ordinal), Properties.Select(p => $"{p.Record.Name}.{p.Property}").Order(StringComparer.Ordinal));
        Assert.All(
            Properties.Where(p => p.Key is not null),
            p => Assert.True(PropertiesOf(p.Definition).TryGetProperty(p.Key!, out _), $"{p.Record.Name}.{p.Property}: the schema's {p.Definition} has no {p.Key}."));
    }

    private static void AssertValid(string json)
    {
        using var instance = JsonDocument.Parse(json);
        Assert.Empty(Schema().Validate(instance.RootElement));
    }

    private static SchemaSubset Schema()
    {
        using var schema = JsonDocument.Parse(File.ReadAllText(SchemaPath));
        return new SchemaSubset(schema.RootElement.Clone());
    }

    private static JsonElement Definition(string name)
    {
        using var schema = JsonDocument.Parse(IrJsonSchema.Write());
        return schema.RootElement.GetProperty("$defs").GetProperty(name).Clone();
    }

    /// <summary>The properties a definition lists: the document's own for "", its source's for "document.source".</summary>
    private static JsonElement PropertiesOf(string definition)
    {
        using var schema = JsonDocument.Parse(IrJsonSchema.Write());
        var root = schema.RootElement.GetProperty("properties");
        return (definition switch
        {
            "" => root,
            "document.source" => root.GetProperty("source").GetProperty("properties"),
            _ => schema.RootElement.GetProperty("$defs").GetProperty(definition).GetProperty("properties"),
        }).Clone();
    }
}
